#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [prefix x | middle | suffix y] -> [suffix y | middle | prefix x]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Element is at position pos, needs to go to position placed
        // Try single operation: we need p[pos] to end up at position placed
        // After op(x,y): suffix [n-y..n-1] goes to [0..y-1], middle [x..n-y-1] goes to [y..n-x-1], prefix [0..x-1] goes to [n-x..n-1]
        // If element is in suffix (pos >= n-y): it goes to position pos-(n-y). We want pos-(n-y)=placed => y=n-pos+placed. x can be anything valid.
        // If element is in prefix (pos < x): it goes to position n-x+pos. We want n-x+pos=placed => x=n+pos-placed. But x<=n-1 and placed<pos usually not.

        // Try: put element in suffix, land at placed
        {
            int y = n - pos + placed; // pos >= n-y => n-y <= pos => y >= n-pos, and y = n-pos+placed >= n-pos. Check: need y>0 (yes if n-pos+placed>0), need x>0, need x+y<n => x < n-y = pos-placed. So x can be placed+1 if placed+1 < pos-placed => 2*placed+1 < pos. Or x=1 if 1 < pos-placed => pos > placed+1.
            if(y > 0 && y < n) {
                int x_max = n - y - 1; // x+y < n => x < n-y
                // x must be > 0 and x <= x_max, and middle must exist (x+y < n guaranteed if x>=1 and x_max>=1)
                // Also element must be in suffix: pos >= n-y = pos-placed. pos >= pos-placed is true if placed>=0. Good.
                // Pick x = min(placed+1, x_max) but x must be >0
                if(x_max >= 1) {
                    // Prefer x = placed (keeps first 'placed' elements if they're already sorted)
                    // Actually we want x such that the first 'placed' elements stay in the middle
                    // Middle goes from [x..n-y-1] to positions [y..n-x-1]. First 'placed' sorted elements are at [0..placed-1].
                    // To keep them: they must be in middle, so x <= placed... but x>0 means some prefix moves.
                    // Hmm, let's just try: use two ops if single doesn't preserve placed elements.
                    // Step 1: move element to last position (pos n-1)
                    if(pos < n-1) {
                        int xx = pos+1, yy = n-1-pos;
                        // xx+yy = n, need < n. So middle is empty. Not valid.
                        // Use xx = pos, yy = n-1-pos if pos>0
                        // After: suffix[pos+1..n-1] | middle[pos..pos] | prefix[0..pos-1]
                        // Element at pos stays at position yy = n-1-pos. Not at end.
                        // Alternative: just use x=1, y=n-1-pos if pos<n-1
                        // suffix=[pos+1..n-1], middle=[1..pos], prefix=[0]
                        // element at pos goes to middle pos [y + (pos-1)] = n-1-pos+pos-1 = n-2. 
                        // Hmm this is getting complicated. Let me just do 2-op approach reliably.

                        // Op1: bring element to position n-1
                        // x=pos-placed, y=n-1-pos, need x>0 => pos>placed (true), y>0 => pos<n-1 (true here), x+y<n => pos-placed+n-1-pos=n-1-placed<n (true)
                        int a = pos - placed, b = n-1-pos;
                        if(a>0 && b>0 && a+b<n) {
                            ops.push_back({a,b});
                            apply(p,a,b);
                        }
                        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                    }
                    if(pos==placed) continue;
                    // Op2: bring from pos to placed
                    if(pos==n-1 && placed+2<=n) {
                        int a=placed+1, b=1;
                        if(a>0&&b>0&&a+b<n) {
                            ops.push_back({a,b});
                            apply(p,a,b);
                        }
                    } else if(pos>placed) {
                        int a=placed+1, b=n-pos;
                        if(a>0&&b>0&&a+b<n) {
                            ops.push_back({a,b});
                            apply(p,a,b);
                        }
                    }
                    continue;
                }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
